\documentclass{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usetikzlibrary{arrows.meta}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    axis lines=middle,
    xlabel=$x$,
    ylabel=$y$,
    xmin=-2.5, xmax=2.5,
    ymin=-1.5, ymax=2.5,
    xtick={-2,-1,0,1,2},
    ytick={-1,0,1,2},
    grid=both,
    minor tick num=1,
    tick style={thin, black},
    axis line style={-Stealth},
    legend pos=north west,
    legend style={draw=none, font=\small},
    every axis plot/.append style={thick, smooth},
    samples=100,
]
% 左侧分支: x<0 时 f(x)=2^x
\addplot[domain=-2:0, blue] {2^x};
% 右侧分支: x>0 时 f(x)=-2^{-x}
\addplot[domain=0:2, red] {-2^(-x)};

% 在 (0,1) 处画空心圆 (左极限点)
\draw[fill=white] (axis cs:0,1) circle[radius=1.5pt];
% 在 (0,-1) 处画空心圆 (右极限点)
\draw[fill=white] (axis cs:0,-1) circle[radius=1.5pt];
% 在 (0,0) 处画实心圆 (孤立点)
\draw[fill=black] (axis cs:0,0) circle[radius=1.5pt];

% 图例与标注
\addlegendentry{$f(x)=2^x,\ x<0$}
\addlegendentry{$f(x)=-2^{-x},\ x>0$}
\node[above left] at (axis cs:0,1) {$(0,1)$ 左极限};
\node[below left] at (axis cs:0,-1) {$(0,-1)$ 右极限};
\node[above right] at (axis cs:0,0) {$(0,0)$ 定义点};

\end{axis}
\end{tikzpicture}
\end{document}
